    for _ in range(2):
        labels = []
        wire_len = 1
        while True:
            if pos >= len(rdata):
                raise RecordError("soa rdata not terminated")
            length = rdata[pos]
            if length == 0:
                pos += 1
                break
            if length > _MAX_LABEL_LEN:
                raise RecordError("soa rdata bad label length")
            pos += 1
            if pos + length > len(rdata):
