        spans = []
        for _ in range(3):
            start = pos
            _value, pos = _read_char_string(rdata, pos)
            spans.append((start, pos))
        name, end = _fold_wire_name(rdata, pos)
        if end != len(rdata):
            return rdata
        strings = b"".join(bytes(rdata[start:stop])
                           for start, stop in spans)
        return bytes(rdata[:4]) + strings + name
    except RecordError:
        return rdata


