    """NSEC 专用规范化：折 next 名，位图逐字节保留。"""
    try:
        name, pos = _fold_wire_name(rdata, 0)
        if pos == len(rdata):
            return rdata  # 位图为空：属非法 NSEC，原样保留
        return name + bytes(rdata[pos:])
    except RecordError:
