        line = bad
    else:
        line = bad + " 100 IN A 1.1.1.1\n"
    try:
        dns.import_master("$ORIGIN example.\n" + SOA_MASTER + line)
        raise AssertionError(bad)
    except dns.ConfigError:
        pass
print("master ConfigError OK")

# dangling backslash
try:
    dns.import_master("$ORIGIN example.\n" + SOA_MASTER
                      + "a\\\n 100 IN A 1.1.1.1\n")
    raise AssertionError
except dns.ConfigError:
    print("dangling backslash ConfigError OK")

# 2. Legal escapes, length violations -> RecordError
try:
    dns.import_master("$ORIGIN example.\n" + SOA_MASTER
                      + "\\065" * 64 + ".example. 100 IN A 1.1.1.1\n")
    raise AssertionError
except dns.RecordError:
    print("label length RecordError OK")

try:
    dns.import_master("$ORIGIN example.\n" + SOA_MASTER
                      + ".".join(["\\097"] * 125)
                      + ".example. 100 IN A 1.1.1.1\n")
    raise AssertionError
except dns.RecordError:
    print("name length RecordError OK")

# 3. Zone/model bad names -> RecordError or ZoneError (valid JSON)
for bad in ["a\\256b.example.", "a\\12b.example.", "a\\", "relative."[:-1]]:
    txt = json.dumps({"version": 2, "origin": bad, "class": 1, "records": []})
    try:
        dns.import_zone(txt)
        raise AssertionError(repr(bad))
    except (dns.RecordError, dns.ZoneError):
        pass
print("zone model name errors OK")

# 4. Policy non-canonical -> PolicyError
for bad in ["A.example.", "a\\065.example.", "a\\092b.example."]:
    try:
        dns._validate_policy_rules(
            [{"client": "*", "name": bad, "type": None, "action": "allow"}])
        raise AssertionError(bad)
    except dns.PolicyError:
        pass
# canonical escaped names accepted
for good in [r"a\092b.example.", r"\201.example.", "a\\046b.example."]:
    dns._validate_policy_rules(
        [{"client": "*", "name": good, "type": None, "action": "allow"}])
print("policy canonical rules OK")

# 5. Wire-format query errors: MessageError / EDNSError
try:
    dns.decode_query(
        b"\x12\x34\x00\x00\x00\x01\x00\x00\x00\x00\x00\x00\x03foo\xc0\x02"
        b"\x00\x01\x00\x01")
    raise AssertionError
except dns.MessageError:
    print("forward pointer MessageError OK")

edns_bad = (b"\x12\x34\x00\x00\x00\x01\x00\x00\x00\x00\x00\x01"
            + b"\x03foo\xc0\x02\x00\x01\x00\x01"
            + b"\x00" + (41).to_bytes(2, "big") + (512).to_bytes(2, "big")
            + b"\x00" * 6)
try:
    dns._decode_edns_query(edns_bad)
    raise AssertionError
except dns.EDNSError:
    print("EDNS pointer error EDNSError OK")

# 6. Failure leaves cache/clock/stats/zone untouched
zone = {
    "origin": "example.",
    "records": SOA_ZONE["records"] + [{
        "name": "ok.example.", "type": 1, "class": 1, "ttl": 100,
        "rdata": bytes([1, 1, 1, 1])}],
}
pc = dns.PositiveCache(zone)
pc.resolve(tq("ok.example."), 0)
stats_before = pc.stats()
# malformed query at later time must not move clock or stats
try:
    pc.resolve(b"\x00" * 12, 1)
    raise AssertionError
except dns.MessageError:
    pass
assert pc.stats() == stats_before
# clock must still be 0: earlier now rejected
try:
    pc.resolve(tq("ok.example."), -1)
    raise AssertionError
except (dns.CacheError, TypeError):
    pass
# now=0 still accepted (last_now unchanged by the failure)
_, hit = pc.resolve(tq("OK.EXAMPLE."), 0)
assert hit is True
assert pc.stats() == stats_before
print("failure atomicity OK")

# 7. decode CLI shape: arbitrary octet name round-trips to canonical text
dec = dns.decode_query(wq([b"a", bytes([0x80, 0x00]), b"z"]))
assert dec["questions"][0]["name"] == r"a.\128\000.z."
assert dns.decode_query(wq([b"*", b"example"]))["questions"][0]["name"] == r"\042.example."
print("canonical decode text OK")
print("ALL ERROR/ATOMICITY TESTS PASSED")

