import dns, json
HDR=b'\x12\x34\x00\x00\x00\x01\x00\x00\x00\x00\x00\x00'
def wn(labs):
    o=b''
    for l in labs:
        if isinstance(l,str): l=l.encode()
        o+=bytes([len(l)])+l
    return o+b'\x00'
def tq(t,qt=1): return HDR+wn(dns._normalize_question_name(t))+qt.to_bytes(2,'big')+b'\x00\x01'
zone={"origin":"example.","records":[
 {"name":"example.","type":6,"class":1,"ttl":100,
  "rdata":wn([b'ns',b'example'])+wn([b'rt',b'example'])+(5).to_bytes(4,'big')*5},
 {"name":"ab.example.","type":1,"class":1,"ttl":100,"rdata":bytes([9,9,9,9])}]}
r=dns.Resolver(zone,[("u",[])],timeout=5)
ops=[{"op":"resolve","query":tq("ab.example.").hex(),"now":1,"limit":512}]
b1=r.export_bundle(ops,1)
res,t=dns.Resolver.replay_bundle(b1)
print("equal:", t==b1)
if t!=b1:
    j1,j2=json.loads(b1),json.loads(t)
    for k in j1:
        if j1[k]!=j2.get(k):
            print("key",k,"differs")
            a,bb=json.dumps(j1[k]),json.dumps(j2[k])
            for i,(x,y) in enumerate(zip(a,bb)):
                if x!=y:
                    print("first diff at",i,repr(a[max(0,i-40):i+40]),"VS",repr(bb[max(0,i-40):i+40])); break
            print("lens",len(a),len(bb))
